package com.hmdp.ai.runtime.tool;
import org.springframework.core.annotation.AnnotatedElementUtils;import org.springframework.stereotype.Component;import java.util.*;
@Component public class LocalSkillRegistry {private final Map<String,LocalSkill>skills;public LocalSkillRegistry(List<LocalSkill> values){Map<String,LocalSkill>m=new HashMap<>();for(LocalSkill s:values){AgentSkill a=AnnotatedElementUtils.findMergedAnnotation(s.getClass(),AgentSkill.class);if(a==null)throw new IllegalStateException("LocalSkill requires @AgentSkill");String k=a.code()+":"+a.version();if(m.put(k,s)!=null)throw new IllegalStateException("duplicate local skill: "+k);}skills=Collections.unmodifiableMap(m);}public LocalSkill require(String code,int version){LocalSkill s=skills.get(code+":"+version);if(s==null)throw new IllegalArgumentException("local skill is not registered: "+code+":"+version);return s;}}
